pam_handle_t *pamh;
const char *authenticated_user = NULL;
struct pam_conv conv = { converse, NULL };
if (pam_start("myservice", user, &conv, &pamh) != PAM_SUCCESS)
    return AUTH_UNAVAILABLE;                       /* the stack lives in /etc/pam.d/myservice */
int rc = pam_authenticate(pamh, 0);
if (rc == PAM_SUCCESS)
    rc = pam_acct_mgmt(pamh, 0);
if (rc == PAM_SUCCESS)
    rc = pam_get_item(pamh, PAM_USER, (const void **)&authenticated_user);
/* authenticated_user is the normalized principal when rc == PAM_SUCCESS */
pam_end(pamh, rc);
